        _sd("EML Differential Algebra: Closure Properties", "Prove that the class of EML functions forms a differential field: closed under addition, multiplication, composition, and differentiation. Show that the inverse function theorem for EML functions yields EML inverses. Determine whether EML functions are closed under integration.", ["EML", "Algebra"], 0.84),
