        _sd("Secret Sharing: Shamir's Scheme and Verifiable Variants", "Prove that Shamir's secret sharing scheme is information-theoretically secure: any t-1 shares reveal zero information about the secret. Formalize Feldman's verifiable secret sharing and prove that cheating dealers are caught. Show that the reconstruction threshold equals the degree of the polynomial plus one.", ["Cryptography", "Algebra"], 0.83),
        _sd("Quantum Key Distribution: BB84 Security Proof", "Formalize the BB84 protocol and prove its unconditional security against arbitrary quantum attacks. Show that the quantum bit error rate threshold for secure key distillation is approximately 11%. Prove that privacy amplification via universal hashing reduces Eve's information to exponentially small.", ["Cryptography", "Physics"], 0.86),
