        _sd("ML Loss Landscape: Critical Points and Saddle Points", "Prove that for overparameterized neural networks, almost all critical points are saddle points, not local minima. Formalize the Hessian spectrum at critical points. Show that the loss landscape satisfies the strict saddle property: the Hessian has a negative eigenvalue at non-minimum critical points. Prove that SGD escapes strict saddles in polynomial time.", ["MachineLearning", "Computation"], 0.83),
